const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const home_contents = require('home_contents')
const contacts_list = require('contacts_list')
const chat_view = require('chat_view')
const details_menu = require('details_menu')
const more_menu = require('more_menu')

module.exports = menu

async function menu(opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: iconject }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="main-container">
      <div class="content-container">
        <div class="chat-overlay hidden">
          <div class="chat-body"></div>
        </div>
      </div>
      <div class="menu-container"></div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const footer = shadow.querySelector('.menu-container')
  const content = shadow.querySelector('.content-container')
  const chat_overlay = shadow.querySelector('.chat-overlay')
  const chat_body = shadow.querySelector('.chat-body')

  let dricons = []
  const subs = await sdb.watch(onbatch)

  // ✅ Create all components once
  const home_component = await home_contents(subs[0])

  // Use the contacts_list_component that home_contents already wired to the backend
  // This ensures the Contacts tab shows live data from contact_list
  const contacts_component = home_component.contacts_list_component || await contacts_list(subs[1])

  const wallet_setup_component = await details_menu(subs[2], home_component.walletSetupProtocol)
  const more_component = await more_menu(subs[3], home_component.moreProtocol)
  let chat_component = null

  contacts_component.addEventListener('open-contact-chat', async event => {
    const contact = event.detail.contact

    if (!chat_component) {
      chat_component = await chat_view(subs[4], {
        contact,
        onClose: () => chat_overlay.classList.add('hidden')
      })
      chat_body.append(chat_component)
    } else {
      chat_component.openContact(contact)
    }

    chat_overlay.classList.remove('hidden')
  })

  // ✅ Append all, hide except Home`
  content.appendChild(home_component)
  content.appendChild(contacts_component)
  content.appendChild(wallet_setup_component)
  content.appendChild(more_component)

  contacts_component.style.display = 'none'
  wallet_setup_component.style.display = 'none'
  more_component.style.display = 'none'

  footer.addEventListener('click', event => {
    const tab = event.target.closest('.tab-container')
    if (!tab) return

    const tabType = tab.dataset.tab
    footer.querySelectorAll('.tab-container').forEach(t => t.classList.remove('active'))
    tab.classList.add('active')

    home_component.style.display = 'none'
    contacts_component.style.display = 'none'
    wallet_setup_component.style.display = 'none'
    more_component.style.display = 'none'

    if (tabType === 'home') home_component.style.display = ''
    if (tabType === 'contacts') contacts_component.style.display = ''
    if (tabType === 'wallet-setup') {
      wallet_setup_component.style.display = ''
      wallet_setup_component.open()
    }
    if (tabType === 'more') {
      more_component.style.display = ''
      if (more_component.open) more_component.open()
    }
  })

  return el

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  async function ondata(data) {
    footer.innerHTML = `
      <div class="tab-container active" data-tab="home">
        <div class="icon">${dricons[0]}</div>
        <div class="label">Home</div>
      </div>
      <div class="tab-container" data-tab="contacts">
        <div class="icon">${dricons[1]}</div>
        <div class="label">Contacts</div>
      </div>
      <div class="tab-container" data-tab="wallet-setup">
        <div class="icon">${dricons[2]}</div>
        <div class="label">Wallet Setup</div>
      </div>
      <div class="tab-container" data-tab="more">
        <div class="icon">${dricons[3]}</div>
        <div class="label">More</div>
      </div>
    `

  }

  function iconject(data) {
    dricons = data
  }

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }
}

